from pathlib import Path

index_path = Path('index.html')
text = index_path.read_text(encoding='utf-8')

if "async function mergeImportJson(file)" in text and "0.28.15" in text:
    print('0.28.15 merge import already applied')
else:
    def replace_once(old, new, label):
        global text
        count = text.count(old)
        if count != 1:
            raise SystemExit(f'{label}: expected 1 match, found {count}')
        text = text.replace(old, new, 1)

    replace_once(
        "else if(a==='export'||a==='backup-now')exportJson();else if(a==='import')document.getElementById('importFile')?.click();else if(a==='csv')downloadCsv();",
        "else if(a==='export'||a==='backup-now')exportJson();else if(a==='import')document.getElementById('importFile')?.click();else if(a==='merge-import')document.getElementById('mergeImportFile')?.click();else if(a==='csv')downloadCsv();",
        'merge-import click action'
    )

    replace_once(
        "if(e.target.id==='importFile'&&e.target.files?.[0])await importJson(e.target.files[0]);if(e.target.id==='arrivalDestination')refreshArrivalEstimates();",
        "if(e.target.id==='importFile'&&e.target.files?.[0]){const file=e.target.files[0];e.target.value='';await importJson(file)}if(e.target.id==='mergeImportFile'&&e.target.files?.[0]){const file=e.target.files[0];e.target.value='';await mergeImportJson(file)}if(e.target.id==='arrivalDestination')refreshArrivalEstimates();",
        'merge-import file handler'
    )

    old_backup_ui = "<details class=\"accordion\"><summary><span class=\"accordion-title\"><strong>Data & back-up</strong><small>${esc(backupStatusText())}</small></span><span class=\"accordion-arrow\">›</span></summary><div class=\"accordion-body\"><div class=\"backup-status\"><strong>${esc(backupStatusText())}</strong><small>GPS-trackpunten: ${trackStoreReady?'IndexedDB':'lokale fallback'} · offline app: ${'serviceWorker' in navigator?'beschikbaar':'niet ondersteund'}</small></div><div class=\"grid2 buttons\" style=\"margin-top:14px\"><button type=\"button\" class=\"btn secondary\" data-action=\"export\">Back-up maken</button><button type=\"button\" class=\"btn secondary\" data-action=\"import\">Back-up importeren</button></div><input id=\"importFile\" type=\"file\" accept=\"application/json\" hidden></div></details>"
    new_backup_ui = "<details class=\"accordion\"><summary><span class=\"accordion-title\"><strong>Data & back-up</strong><small>${esc(backupStatusText())}</small></span><span class=\"accordion-arrow\">›</span></summary><div class=\"accordion-body\"><div class=\"backup-status\"><strong>${esc(backupStatusText())}</strong><small>GPS-trackpunten: ${trackStoreReady?'IndexedDB':'lokale fallback'} · offline app: ${'serviceWorker' in navigator?'beschikbaar':'niet ondersteund'}</small></div><div class=\"grid2 buttons\" style=\"margin-top:14px\"><button type=\"button\" class=\"btn secondary\" data-action=\"export\">Back-up maken</button><button type=\"button\" class=\"btn secondary\" data-action=\"import\">Back-up herstellen</button><button type=\"button\" class=\"btn secondary\" data-action=\"merge-import\">Gegevens toevoegen</button></div><div class=\"hint\" style=\"margin-top:10px\"><strong>Herstellen</strong> vervangt de huidige registratie. <strong>Gegevens toevoegen</strong> houdt bestaande gegevens en slaat alleen nieuwe onderdelen op; dubbelen worden overgeslagen.</div><input id=\"importFile\" type=\"file\" accept=\"application/json\" hidden><input id=\"mergeImportFile\" type=\"file\" accept=\"application/json\" hidden></div></details>"
    replace_once(old_backup_ui, new_backup_ui, 'data and backup controls')

    old_import = "async function importJson(file){try{const x=JSON.parse(await file.text());if(!confirm('Bestaande gegevens vervangen door deze back-up?'))return;data=normalize(x);if('indexedDB' in window){try{await replaceTrackStore(data.trackPoints);trackStoreReady=true}catch(e){console.warn('GPS-import gebruikt lokale fallback',e);trackStoreReady=false}}save();render();toast('Back-up geïmporteerd.')}catch(e){showError('Back-up kon niet worden gelezen.')}}"
    new_import = r'''async function importJson(file){try{const x=JSON.parse(await file.text());if(!confirm('Bestaande gegevens vervangen door deze back-up?'))return;data=normalize(x);if('indexedDB' in window){try{await replaceTrackStore(data.trackPoints);trackStoreReady=true}catch(e){console.warn('GPS-import gebruikt lokale fallback',e);trackStoreReady=false}}save();render();toast('Back-up hersteld.')}catch(e){showError('Back-up kon niet worden gelezen.')}}
function mergeNorm(v){return String(v??'').trim().toLocaleLowerCase('nl-NL').replace(/\s+/g,' ')}
function mergeTimeKey(v){const d=new Date(v);return Number.isNaN(d.getTime())?String(v||''):String(Math.floor(d.getTime()/60000))}
function mergeLocationFingerprint(l){if(!l)return'';const lat=Number.isFinite(+l.lat)?(+l.lat).toFixed(5):'',lng=Number.isFinite(+l.lng)?(+l.lng).toFixed(5):'';return[mergeNorm(l.name),mergeNorm(l.address),lat,lng].join('|')}
function mergeLocationMatch(l,pool=data.locations){if(!l)return null;if(l.id){const byId=pool.find(x=>x.id===l.id);if(byId)return byId}const name=mergeNorm(l.name),address=mergeNorm(l.address);if(name&&address){const exact=pool.find(x=>mergeNorm(x.name)===name&&mergeNorm(x.address)===address);if(exact)return exact}if(name&&l.lat!=null&&l.lng!=null){const near=pool.find(x=>mergeNorm(x.name)===name&&x.lat!=null&&x.lng!=null&&distance(l,x)<75);if(near)return near}return null}
function mergeTripSignature(t){return[mergeTimeKey(t?.departureTime),num(t?.startOdometer)??'',num(t?.endOdometer)??'',mergeLocationFingerprint(t?.origin),mergeLocationFingerprint(t?.destination)].join('::')}
function mergeEventSignature(ev){return[String(ev?.type||''),String(ev?.tripId||''),mergeTimeKey(ev?.time),num(ev?.odometer)??'',mergeLocationFingerprint(ev?.location)].join('::')}
function mergePointSignature(p){const lat=Number.isFinite(+p?.lat)?(+p.lat).toFixed(5):'',lng=Number.isFinite(+p?.lng)?(+p.lng).toFixed(5):'';return[String(p?.tripId||''),mergeTimeKey(p?.time),lat,lng].join('::')}
function remapMergeSnapshot(l,locationIdMap){if(!l)return l;const copy=clone(l),mapped=l.id?locationIdMap.get(l.id):null;if(mapped){copy.id=mapped;return copy}const existing=mergeLocationMatch(l);if(existing)copy.id=existing.id;return copy}
function mergeBackupData(source){if(!source||typeof source!=='object')throw new Error('Geen geldige back-up.');const incoming=normalize(source),stats={locationsAdded:0,locationsMatched:0,tripsAdded:0,tripsSkipped:0,eventsAdded:0,eventsSkipped:0,trackPointsAdded:0,trackPointsSkipped:0,newTrackPoints:[]},locationIdMap=new Map(),usedLocationIds=new Set(data.locations.map(x=>x.id).filter(Boolean));for(const l of incoming.locations){if(!l||typeof l!=='object')continue;const existing=mergeLocationMatch(l);if(existing){if(l.id)locationIdMap.set(l.id,existing.id);stats.locationsMatched++;continue}const copy=clone(l);let id=String(copy.id||'');if(!id||usedLocationIds.has(id))id=uid();copy.id=id;data.locations.push(copy);usedLocationIds.add(id);if(l.id)locationIdMap.set(l.id,id);stats.locationsAdded++}const existingTripsById=new Map(data.trips.filter(t=>t?.id).map(t=>[t.id,t])),tripBySignature=new Map(data.trips.map(t=>[mergeTripSignature(t),t])),tripIdMap=new Map();for(const t of incoming.trips){if(!t||typeof t!=='object')continue;const candidate={...clone(t),origin:remapMergeSnapshot(t.origin,locationIdMap),destination:remapMergeSnapshot(t.destination,locationIdMap)};let duplicate=t.id?existingTripsById.get(t.id):null;if(!duplicate)duplicate=tripBySignature.get(mergeTripSignature(candidate));if(duplicate){if(t.id)tripIdMap.set(t.id,duplicate.id);stats.tripsSkipped++;continue}let id=String(candidate.id||'');if(!id||existingTripsById.has(id))id=uid();candidate.id=id;data.trips.push(candidate);existingTripsById.set(id,candidate);tripBySignature.set(mergeTripSignature(candidate),candidate);if(t.id)tripIdMap.set(t.id,id);stats.tripsAdded++}const existingEventsById=new Map(data.events.filter(ev=>ev?.id).map(ev=>[ev.id,ev])),eventSignatures=new Set(data.events.map(mergeEventSignature));for(const ev of incoming.events){if(!ev||typeof ev!=='object')continue;const mappedTripId=ev.tripId?(tripIdMap.get(ev.tripId)||(existingTripsById.has(ev.tripId)?ev.tripId:null)):null,candidate={...clone(ev),tripId:mappedTripId,location:remapMergeSnapshot(ev.location,locationIdMap)};let duplicate=ev.id?existingEventsById.get(ev.id):null;const sig=mergeEventSignature(candidate);if(!duplicate&&eventSignatures.has(sig))duplicate=true;if(duplicate){stats.eventsSkipped++;continue}let id=String(candidate.id||'');if(!id||existingEventsById.has(id))id=uid();candidate.id=id;data.events.push(candidate);existingEventsById.set(id,candidate);eventSignatures.add(sig);stats.eventsAdded++}const pointIds=new Set(data.trackPoints.map(p=>p?.id).filter(Boolean)),pointSignatures=new Set(data.trackPoints.map(mergePointSignature));for(const p of incoming.trackPoints){if(!p||typeof p!=='object')continue;const mappedTripId=p.tripId?(tripIdMap.get(p.tripId)||(existingTripsById.has(p.tripId)?p.tripId:null)):null;if(!mappedTripId){stats.trackPointsSkipped++;continue}const candidate={...clone(p),tripId:mappedTripId},sig=mergePointSignature(candidate);if(pointSignatures.has(sig)){stats.trackPointsSkipped++;continue}let minute='';try{minute=new Date(candidate.time).toISOString().slice(0,16)}catch(_){}let id=minute?`${mappedTripId}_${minute}`:String(candidate.id||uid());if(pointIds.has(id)){stats.trackPointsSkipped++;continue}candidate.id=id;data.trackPoints.push(candidate);stats.newTrackPoints.push(candidate);pointIds.add(id);pointSignatures.add(sig);stats.trackPointsAdded++}return stats}
async function mergeImportJson(file){try{const x=JSON.parse(await file.text());if(!x||typeof x!=='object')throw new Error('Geen geldige back-up.');const incoming=normalize(x),summary=[`${incoming.trips.length} ritten`,`${incoming.locations.length} locaties`,`${incoming.events.length} extra registraties`].join(', ');if(!confirm(`Gegevens uit deze back-up toevoegen?\n\n${summary}.\n\nJe huidige gegevens, instellingen en eventuele actieve rit blijven behouden. Dubbelen worden overgeslagen.`))return;const stats=mergeBackupData(incoming);if(trackStoreReady&&stats.newTrackPoints.length){try{await putTrackPoints(stats.newTrackPoints)}catch(e){console.warn('GPS-samenvoeging gebruikt lokale fallback',e);trackStoreReady=false}}rebuildLast();save();render();const added=stats.tripsAdded+stats.locationsAdded+stats.eventsAdded+stats.trackPointsAdded;if(!added){toast(`Geen nieuwe gegevens gevonden · ${stats.tripsSkipped} ritten overgeslagen.`);return}toast(`${stats.tripsAdded} ritten · ${stats.locationsAdded} locaties · ${stats.eventsAdded} registraties toegevoegd.`)}catch(e){console.error(e);showError('Gegevens konden niet worden toegevoegd. Controleer het back-upbestand.')}}'''
    replace_once(old_import, new_import, 'merge import implementation')

    replace_once("+' · 0.28.14';", "+' · 0.28.15';", 'app version')
    index_path.write_text(text, encoding='utf-8')

sw_path = Path('service-worker.js')
sw = sw_path.read_text(encoding='utf-8')
if "kmreg-shell-0.28.15" not in sw:
    if sw.count("kmreg-shell-0.28.14") != 1:
        raise SystemExit('service worker: expected 0.28.14 cache once')
    sw = sw.replace("kmreg-shell-0.28.14", "kmreg-shell-0.28.15", 1)
    sw_path.write_text(sw, encoding='utf-8')
